import{_ as t,o as a,c as i,a6 as s}from"./chunks/framework.CKIbuWFA.js";const u=JSON.parse('{"title":"插件运行时与信任限制","description":"","frontmatter":{"title":"插件运行时与信任限制","docId":"developer.plugins.runtimes","translationKey":"developer.plugins.runtimes","locale":"zh","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6a249fa36fa53f3bfe7da57fdd25a445e593517946f80ac7e891b54d95cdc17d","translationRevision":"a9fbb1dbd420181e36cbc26996750d240299592c7fc8b211e106b46003712f80","order":260},"headers":[],"relativePath":"zh/developer/plugins/runtimes.md","filePath":"zh/developer/plugins/runtimes.md","lastUpdated":1794611623000}'),d={name:"zh/developer/plugins/runtimes.md"};function r(n,e,o,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="plugin-runtimes-and-trust-limits" tabindex="-1">插件运行时与信任限制 <a class="header-anchor" href="#plugin-runtimes-and-trust-limits" aria-label="Permalink to &quot;插件运行时与信任限制 {#plugin-runtimes-and-trust-limits}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>选择依赖和信任与宿主匹配的可执行格式。先阅读<a href="./">插件概览</a>，针对实际构建验证清单，加载代码前检查目标特定限制。协议兼容、原生 ABI 兼容及权限授予是独立检查。</p><h2 id="choose-an-implemented-runtime" tabindex="-1">选择已实现的运行时 <a class="header-anchor" href="#choose-an-implemented-runtime" aria-label="Permalink to &quot;选择已实现的运行时 {#choose-an-implemented-runtime}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>运行时</th><th>执行方式</th><th>信任与可移植性</th></tr></thead><tbody><tr><td><code>native</code></td><td><code>libloading</code> C ABI</td><td>受信任的进程内代码；目标特定</td></tr><tr><td><code>process</code></td><td>独立可执行文件，带帧的 stdin/stdout</td><td>崩溃隔离，使用普通用户操作系统权限</td></tr><tr><td><code>napi-vm</code></td><td>通过 <code>rquickjs</code> 在 QuickJS 上运行预编译 JS</td><td>默认拒绝宿主效果；可选原生扩展会改变信任</td></tr><tr><td><code>declarative</code></td><td>经验证的集成描述符</td><td>没有客体程序；效果通过宿主代理</td></tr><tr><td><code>wasm</code></td><td>可选运行时槽位</td><td>常规构建未启用通用引擎</td></tr></tbody></table><p>原生 ABI v1 通过小型 C 表交换序列化字节；Rust 容器、trait 对象和 future 不跨越此边界。原生库保持加载直到关闭。进程帧使用小端 u32 长度，随后是 JSON 字节，并非换行分隔的控制 RPC。诊断输出必须避开带帧的 stdout 通道。</p><h2 id="understand-quickjs-compatibility" tabindex="-1">理解 QuickJS 兼容性 <a class="header-anchor" href="#understand-quickjs-compatibility" aria-label="Permalink to &quot;理解 QuickJS 兼容性 {#understand-quickjs-compatibility}&quot;">​</a></h2><p>清单名称 <code>napi-vm</code> 保持稳定，但旧文档关于独立纯 Rust 解释器的描述已属历史。客体获得文档说明的兼容全局对象，不是完整 Node 环境。不支持 <code>napi_get_uv_event_loop</code>。原生 <code>.node</code> 扩展使用有意受信任、允许列表控制及 SHA-256 验证的进程内路径；JavaScript 运行时名称不会使其变得安全。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-plugin-loader</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lib</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages</span></span></code></pre></div><p>完整原生扩展夹具需要不可用的平台工具时，使用针对性加载器测试。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>清单解析会在加载前拒绝不支持的协议/ABI 组合。Android 允许可移植 QuickJS 及有效 Android/Bionic 进程入口，但拒绝原生动态库和 <code>.node</code> 扩展。桌面 Linux/glibc 产物不是 Android 进程插件。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>替换原生库后，重启私有宿主。如果启动超时并变为不确定状态，管理器可保留工作线程身份并阻止替换；不要宣称已成功关闭来绕过该状态。事件缓冲有界，投递可能报告滞后；启动时发出的事件不是持久队列。<a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-plugin-loader/src" target="_blank" rel="noreferrer">加载器实现</a>负责当前引擎及生命周期行为。</p><h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运行细节 {#operational-details}&quot;">​</a></h2><p>当前加载器限制为 QuickJS 内存 512 MiB、栈 2 MiB、每次调用的中断预算、协议帧 16 MiB，以及每实例最多 128 个排队调用。这些限制不保证取消副作用。进程调用超时后会终止并移除进程；原生调用不能安全强杀，因此保留实例，OS 副作用也可能已经发生。替换或重试前检查原始结果和生命周期。可信 <code>.node</code> 插件使用宿主进程权限，在 JS 能力边界之外运行。</p>`,16)])])}const k=t(d,[["render",r]]);export{u as __pageData,k as default};
